from test_branding import test, tests

test('Visual control/grid audit DRUID enUS', "local make=CreateFrame; CreateFrame=function(kind,name,parent,template) local f=make(kind,name,parent,template); f.testTemplate=template; f.SetSize=function(s,w,h) s.testWidth=w; s.testHeight=h end; f.SetPoint=function(s,...) s.testPoint={...} end; f.SetBackdrop=function(s,v) s.testBackdrop=v end; return f end; UnitClass=function() return 'Class','DRUID' end; local id=BuffTap.action.id; BuffTap:Options(); local f=BuffTap.options; assert(f.closeButton.testTemplate=='UIPanelButtonTemplate' and not f.closeButton.testBackdrop); assert(f.tabs[1].testTemplate=='BackdropTemplate'); assert(f.weaponApply.testPoint[2]==180 and f.weaponApply.testWidth==502); for _,p in pairs(f.coatingPickers) do assert(p.testPoint[2]==180 and p.testWidth==502 and p.testPoint[2]+p.testWidth==f.weaponRetry.testPoint[2]+f.weaponRetry.testWidth and p.menu.testWidth==p.testWidth) end; for _,row in ipairs(f.buffRows) do assert(not row.up.testBackdrop and not row.down.testBackdrop,'arrows') end; for i=1,8 do f.selectTab(i); assert(f.pages[i].shown) end; assert(BuffTap.action.id==id,'action')", locale='enUS')
